package stats

import (
	"bufio"
	"compress/gzip"
	"embed"
	"flag"
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// The accuracy fixtures are generated by testdata/gen/gen.py from mpmath at
// high precision (see testdata/gen/common.py). Each row carries the exact
// value as a double-double (hi + lo) and the value SciPy returns for the
// same arguments; the error of both is measured here, the same way.

//go:embed testdata/fixtures/*.tsv.gz
var fixtureFS embed.FS

// The budgets measured by TestAccuracyBudgets, one file per fixture so that
// distributions can be added without touching a shared file.
//
//go:embed testdata/budgets
var budgetFS embed.FS

// measuredBudgets reads testdata/budgets/<fixture>.txt: lines "region budget".
func measuredBudget(name, region string) (float64, bool) {
	b, err := budgetFS.ReadFile("testdata/budgets/" + name + ".txt")
	if err != nil {
		return 0, false
	}
	for _, line := range strings.Split(string(b), "\n") {
		f := strings.Fields(line)
		if len(f) == 2 && f[0] == region {
			v, err := strconv.ParseFloat(f[1], 64)
			return v, err == nil
		}
	}
	return 0, false
}

var (
	accuracyTable   = flag.String("accuracy.table", "", "write the ULP comparison table (markdown) to this file")
	accuracyBudgets = flag.Bool("accuracy.budgets", false, "write testdata/budgets/<fixture>.txt (1.5x the measured max, at least 1 ulp) for the cases registered without explicit budgets")
	accuracyOnly    = flag.String("accuracy.only", "", "with -accuracy.budgets: only fixtures whose name has this prefix")
)

type fixtureRow struct {
	region string
	args   []float64
	hi, lo float64
	sp     float64
	hasSP  bool
}

// accCase registers one fixture: the function under test and the maximum
// error in ULPs allowed per region ("*" is the default budget).
type accCase struct {
	name   string
	fn     func(a []float64) float64
	budget map[string]float64
}

var accCases = map[string]accCase{}

// register is called from the init functions of the per-family test files.
func register(name string, fn func(a []float64) float64, budget map[string]float64) {
	if _, dup := accCases[name]; dup {
		panic("duplicate accuracy case " + name)
	}
	accCases[name] = accCase{name, fn, budget}
}

func loadFixture(tb testing.TB, name string) []fixtureRow {
	tb.Helper()
	f, err := fixtureFS.Open("testdata/fixtures/" + name + ".tsv.gz")
	if err != nil {
		tb.Fatalf("fixture %s: %v", name, err)
	}
	defer f.Close()
	gz, err := gzip.NewReader(f)
	if err != nil {
		tb.Fatalf("fixture %s: %v", name, err)
	}
	var rows []fixtureRow
	sc := bufio.NewScanner(gz)
	sc.Buffer(make([]byte, 1<<16), 1<<20)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || line[0] == '#' {
			continue
		}
		cols := strings.Split(line, "\t")
		if len(cols) < 5 {
			tb.Fatalf("fixture %s: short row %q", name, line)
		}
		var r fixtureRow
		r.region = cols[0]
		nums := make([]float64, len(cols)-2)
		for i, c := range cols[1 : len(cols)-1] {
			v, err := strconv.ParseFloat(c, 64)
			if err != nil {
				tb.Fatalf("fixture %s: %q: %v", name, line, err)
			}
			nums[i] = v
		}
		n := len(nums)
		r.args = nums[:n-2]
		r.hi, r.lo = nums[n-2], nums[n-1]
		if sp := cols[len(cols)-1]; sp != "-" {
			v, err := strconv.ParseFloat(sp, 64)
			if err != nil {
				tb.Fatalf("fixture %s: %q: %v", name, line, err)
			}
			r.sp, r.hasSP = v, true
		}
		rows = append(rows, r)
	}
	if err := sc.Err(); err != nil {
		tb.Fatal(err)
	}
	return rows
}

// ulp returns the spacing of float64 values at |x| (2^(e-52) for x in
// [2^e, 2^(e+1))), and the smallest subnormal for |x| below the normal range.
func ulp(x float64) float64 {
	x = math.Abs(x)
	if x < 0x1p-1022 {
		return 0x1p-1074
	}
	if math.IsInf(x, 0) {
		return math.Inf(1)
	}
	_, e := math.Frexp(x) // x = f*2^e, f in [0.5, 1)
	return math.Ldexp(1, e-53)
}

// ulpErr measures |got - (hi+lo)| in units of ulp(hi). A NaN expected value
// must be matched by NaN, an infinite one exactly; anything else is +Inf.
func ulpErr(got, hi, lo float64) float64 {
	switch {
	case math.IsNaN(hi):
		if math.IsNaN(got) {
			return 0
		}
		return math.Inf(1)
	case math.IsNaN(got):
		return math.Inf(1)
	case math.IsInf(hi, 0):
		if got == hi {
			return 0
		}
		return math.Inf(1)
	case math.IsInf(got, 0):
		return math.Inf(1)
	}
	d := (got - hi) - lo
	return math.Abs(d) / ulp(hi)
}

type errStats struct {
	n         int
	max, p999 float64
	worst     []float64 // arguments of the worst point
}

func summarise(errs []float64, args [][]float64) errStats {
	if len(errs) == 0 {
		return errStats{}
	}
	idx := make([]int, len(errs))
	for i := range idx {
		idx[i] = i
	}
	sort.Slice(idx, func(a, b int) bool { return errs[idx[a]] < errs[idx[b]] })
	n := len(errs)
	q := int(math.Ceil(0.999*float64(n))) - 1
	return errStats{n: n, max: errs[idx[n-1]], p999: errs[idx[q]], worst: args[idx[n-1]]}
}

type regionResult struct {
	region      string
	ours, scipy errStats
	hasSP       bool
}

func measureAcc(c accCase, rows []fixtureRow) []regionResult {
	byRegion := map[string][]fixtureRow{}
	var order []string
	for _, r := range rows {
		if _, ok := byRegion[r.region]; !ok {
			order = append(order, r.region)
		}
		byRegion[r.region] = append(byRegion[r.region], r)
	}
	var out []regionResult
	for _, reg := range order {
		rs := byRegion[reg]
		var eo, es []float64
		var ao, as [][]float64
		hasSP := false
		for _, r := range rs {
			eo = append(eo, ulpErr(c.fn(r.args), r.hi, r.lo))
			ao = append(ao, r.args)
			if r.hasSP {
				hasSP = true
				es = append(es, ulpErr(r.sp, r.hi, r.lo))
				as = append(as, r.args)
			}
		}
		out = append(out, regionResult{reg, summarise(eo, ao), summarise(es, as), hasSP})
	}
	return out
}

func budgetFor(c accCase, region string) float64 {
	if c.budget == nil {
		if b, ok := measuredBudget(c.name, region); ok {
			return b
		}
		return 1
	}
	if b, ok := c.budget[region]; ok {
		return b
	}
	if b, ok := c.budget["*"]; ok {
		return b
	}
	return 1
}

func sortedCases() []accCase {
	var cs []accCase
	for _, c := range accCases {
		cs = append(cs, c)
	}
	sort.Slice(cs, func(i, j int) bool { return cs[i].name < cs[j].name })
	return cs
}

// TestAccuracy holds every function to its per-region ULP budget against the
// mpmath fixtures.
func TestAccuracy(t *testing.T) {
	for _, c := range sortedCases() {
		t.Run(c.name, func(t *testing.T) {
			rows := loadFixture(t, c.name)
			if len(rows) == 0 {
				t.Fatal("empty fixture")
			}
			for _, r := range measureAcc(c, rows) {
				b := budgetFor(c, r.region)
				if !(r.ours.max <= b) {
					t.Errorf("%s/%s: max error %.3g ulp > budget %g (n=%d, worst at %v)",
						c.name, r.region, r.ours.max, b, r.ours.n, r.ours.worst)
				}
			}
		})
	}
}

// TestFixturesRegistered fails when a fixture file has no registered case
// (a fixture nobody checks is worse than none).
func TestFixturesRegistered(t *testing.T) {
	ents, err := fixtureFS.ReadDir("testdata/fixtures")
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range ents {
		name := strings.TrimSuffix(e.Name(), ".tsv.gz")
		if _, ok := accCases[name]; !ok {
			t.Errorf("fixture %s has no registered accuracy case", name)
		}
	}
}

func fmtULP(x float64) string {
	switch {
	case math.IsInf(x, 1):
		return "wrong"
	case x == 0:
		return "0"
	case x < 10:
		return strconv.FormatFloat(x, 'f', 2, 64)
	case x < 1e6:
		return strconv.FormatFloat(x, 'f', 0, 64)
	default:
		return strconv.FormatFloat(x, 'e', 1, 64)
	}
}

// TestAccuracyTable writes docs/accuracy-table.md when run with
// -accuracy.table=PATH: a per-function summary, then every region. It is
// generated, never edited by hand.
func TestAccuracyTable(t *testing.T) {
	if *accuracyTable == "" {
		t.Skip("set -accuracy.table=PATH to write the table")
	}
	type fnRow struct {
		name             string
		n, regions, wins int
		omax, smax       float64
		hasSP            bool
		rows             []regionResult
	}
	var fns []fnRow
	for _, c := range sortedCases() {
		f := fnRow{name: c.name}
		for _, r := range measureAcc(c, loadFixture(t, c.name)) {
			f.rows = append(f.rows, r)
			f.n += r.ours.n
			f.regions++
			f.omax = math.Max(f.omax, r.ours.max)
			if r.hasSP {
				f.hasSP = true
				f.smax = math.Max(f.smax, r.scipy.max)
				if r.ours.max <= r.scipy.max {
					f.wins++
				}
			}
		}
		fns = append(fns, f)
	}
	var b strings.Builder
	b.WriteString("<!-- generated by: go test -run TestAccuracyTable -accuracy.table=docs/accuracy-table.md -->\n\n")
	b.WriteString("## Summary (worst region of each function)\n\n")
	b.WriteString("Errors in ULPs against mpmath; **bold**: at least as accurate as SciPy in every region.\n\n")
	b.WriteString("| function | points | regions | ours max | SciPy max | regions where ours <= SciPy |\n")
	b.WriteString("|---|--:|--:|--:|--:|--:|\n")
	for _, f := range fns {
		sm, w := "n/a", "n/a"
		name := f.name
		if f.hasSP {
			sm, w = fmtULP(f.smax), fmt.Sprintf("%d/%d", f.wins, f.regions)
			if f.wins == f.regions {
				name = "**" + name + "**"
			}
		}
		fmt.Fprintf(&b, "| %s | %d | %d | %s | %s | %s |\n", name, f.n, f.regions, fmtULP(f.omax), sm, w)
	}
	b.WriteString("\n## Every region\n\n")
	b.WriteString("| function | region | points | ours max | ours p99.9 | SciPy max | SciPy p99.9 |\n")
	b.WriteString("|---|---|--:|--:|--:|--:|--:|\n")
	for _, f := range fns {
		for _, r := range f.rows {
			sm, sq := "n/a", "n/a"
			if r.hasSP {
				sm, sq = fmtULP(r.scipy.max), fmtULP(r.scipy.p999)
			}
			om, oq := fmtULP(r.ours.max), fmtULP(r.ours.p999)
			if r.hasSP && r.ours.max <= r.scipy.max {
				om = "**" + om + "**"
			}
			fmt.Fprintf(&b, "| %s | %s | %d | %s | %s | %s | %s |\n", f.name, r.region, r.ours.n, om, oq, sm, sq)
		}
	}
	if err := os.WriteFile(*accuracyTable, []byte(b.String()), 0o644); err != nil {
		t.Fatal(err)
	}
}

// budgetOf rounds a measured maximum up to a budget: 1.5 times the maximum,
// at least 1 ulp, rounded up to two significant digits.
func budgetOf(max float64) float64 {
	b := math.Max(1, 1.5*max)
	if math.IsInf(b, 0) {
		return b
	}
	e := math.Pow(10, math.Floor(math.Log10(b))-1)
	return math.Ceil(b/e) * e
}

// TestAccuracyBudgets writes the measured budgets with -accuracy.budgets.
func TestAccuracyBudgets(t *testing.T) {
	if !*accuracyBudgets {
		t.Skip("set -accuracy.budgets to write testdata/budgets")
	}
	for _, c := range sortedCases() {
		if c.budget != nil || !strings.HasPrefix(c.name, *accuracyOnly) {
			continue
		}
		var b strings.Builder
		for _, r := range measureAcc(c, loadFixture(t, c.name)) {
			v := budgetOf(r.ours.max)
			if math.IsInf(v, 0) {
				t.Errorf("%s/%s: infinite error cannot be budgeted", c.name, r.region)
				continue
			}
			fmt.Fprintf(&b, "%s %g\n", r.region, v)
		}
		if err := os.WriteFile("testdata/budgets/"+c.name+".txt", []byte(b.String()), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}
